import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';

const TimeTrackerPage = () => {
  const location = useLocation();
  const [allTimeLogs, setAllTimeLogs] = useState([]); // Will hold ALL time logs from an API
  const [isLoading, setIsLoading] = useState(true);

  // In a real app, you would fetch this from '/api/timelogs/'. 
  // For now, we simulate this data, including a 'discrepancy' flag.
  const mockTimeLogs = [
    { id: 1, employee_id: 1, name: 'Dr. Anjali Rao', department: 'Computer Science', clockIn: '09:05 AM', clockOut: '05:00 PM', status: 'Completed', discrepancy: false },
    { id: 2, employee_id: 2, name: 'Prof. Vikram Kumar', department: 'Mathematics', clockIn: '09:35 AM', clockOut: '05:10 PM', status: 'Discrepancy', discrepancy: true },
    { id: 3, employee_id: 3, name: 'Dr. Priya Mehta', department: 'Physics', clockIn: '--:--', clockOut: '--:--', status: 'On Leave', discrepancy: false },
    { id: 4, employee_id: 4, name: 'Rajesh Singh', department: 'Administration', clockIn: '08:50 AM', clockOut: '04:55 PM', status: 'Completed', discrepancy: false },
    { id: 5, employee_id: 5, name: 'Sunita Sharma', department: 'Administration', clockIn: '09:02 AM', clockOut: '04:30 PM', status: 'Discrepancy', discrepancy: true },
  ];

  useEffect(() => {
    // Simulating the fetch call
    const fetchTimeLogs = () => {
      setIsLoading(true);
      setTimeout(() => {
        setAllTimeLogs(mockTimeLogs);
        setIsLoading(false);
      }, 500); // Simulate network delay
    };
    fetchTimeLogs();
  }, []);

  // Get the array of selected IDs passed from the Staff Directory
  const selectedIds = location.state?.selectedEmployeeIds;

  // Filter the fetched logs based on the received IDs
  const logsToDisplay = selectedIds && selectedIds.length > 0
    ? allTimeLogs.filter(log => selectedIds.includes(log.employee_id))
    : allTimeLogs;

  // This function would send an update to the backend
  const handleDiscrepancy = (logId, action) => {
    console.log(`Action: ${action} for Time Log ID: ${logId}`);
    // In a real app: await axios.post(`/api/timelogs/${logId}/resolve/`, { action });
    // Then re-fetch the data to show the change.
    alert(`Discrepancy for log ${logId} has been marked as '${action}'. (Simulation)`);
  };

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'Completed': return 'bg-green-100 text-green-800';
      case 'Discrepancy': return 'bg-yellow-100 text-yellow-800';
      case 'On Leave': return 'bg-orange-100 text-orange-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Daily Time Tracker</h1>
          <p className="text-sm text-subtext-light">Review and resolve any time discrepancies.</p>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm overflow-x-auto">
        {isLoading ? (
          <div className="text-center py-8 text-subtext-light">Loading time log data...</div>
        ) : (
          <table className="w-full text-sm text-left">
            <thead className="text-xs uppercase bg-background-light">
              <tr>
                <th className="px-6 py-3">Employee Name</th>
                <th className="px-6 py-3">Department</th>
                <th className="px-6 py-3">Clock In</th>
                <th className="px-6 py-3">Clock Out</th>
                <th className="px-6 py-3">Status</th>
                <th className="px-6 py-3 text-center">Actions</th>
              </tr>
            </thead>
            <tbody>
              {logsToDisplay.map((log) => (
                <tr key={log.id} className="border-b hover:bg-gray-50">
                  <td className="px-6 py-4 font-medium text-text-light dark:text-white">
                    {log.name}
                  </td>
                  <td className="px-6 py-4">{log.department}</td>
                  <td className={`px-6 py-4 ${log.discrepancy ? 'text-red-500 font-semibold' : ''}`}>{log.clockIn}</td>
                  <td className={`px-6 py-4 ${log.discrepancy ? 'text-red-500 font-semibold' : ''}`}>{log.clockOut}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(log.status)}`}>
                      {log.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center space-x-2">
                    {/* Conditionally render buttons ONLY for discrepancies */}
                    {log.status === 'Discrepancy' ? (
                      <>
                        <button
                          onClick={() => handleDiscrepancy(log.id, 'Accepted')}
                          className="text-green-600 hover:underline text-xs font-medium"
                        >
                          Accept
                        </button>
                        <button
                          onClick={() => handleDiscrepancy(log.id, 'Rejected')}
                          className="text-red-600 hover:underline text-xs font-medium"
                        >
                          Reject
                        </button>
                      </>
                    ) : (
                      <span className="text-xs text-subtext-light">--</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default TimeTrackerPage;
